#! /usr/bin/env python

# Script to generate Krona plot given a PSI-BLAST output file and (optionally)
# the accessions of the match genes to be plotted. If no accessions are provided,
# generates a Krona plot of all the matches in the PSI-BLAST output file.

# PSI-BLAST output should be the same as that which is generated by
# the AcrVis pipeline:
#   -outfmt "6 qacc sacc pident qlen slen evalue"

import argparse
import os.path as path
from random import randint
import subprocess
import os
import glob

parser = argparse.ArgumentParser("Generate Krona plot given PSI-BLAST output generated by the GNAT pipeline and (optionally) the accessions of the match genes to be plotted.")
parser.add_argument("psiblast_outfile", help="Path to the file containing the (parsed) PSI-BLAST output. Should be in the same format as that which is generated by the GNAT pipeline. The file of interest ends in .parsed (for the parsed output) or .out (for the raw output). If you use the raw PSI-BLAST output, the script will not work unless you specify the [-r|[--raw] flag.")
parser.add_argument("-g", "--gb_dir", help="Directory containing the GenBank files to generate a Krona plot for. If not provided, a Krona plot for all the matches in the PSI-BLAST output file will be generated. Ensure the file names in the provided directory match the format generated by GNAT (accession is at filename.split('_')[-2]). The accession in the filename must also be present in the PSI-BLAST output file.")
# parser.add_argument("gb_files", nargs="*", help="Optional space-deliminated genbank GN filenames to generate a Krona plot for. (make sure filenames are in the format generated by GNAT (accession is at filename.split('_')[-2])) If no filenames are provided, a Krona plot of all the matches in the PSI-BLAST output file will be generated. Another important note: the accession in the filename must be present in the PSI-BLAST output file.")
parser.add_argument("-o", "--output", help="Name and location of file to output. Defaults to ./blast.krona", default="./blast.krona")
parser.add_argument("-r", "--raw", action='store_true', help="Specify this flag if the raw PSI-BLAST output is being used, or else the script will not work.")

args = parser.parse_args()

# Parse psiblast file
if path.exists(args.psiblast_outfile):
    with open(args.psiblast_outfile, "r") as f:
        # Since we have to iterate over the lines here anyway, might
        # as well modify the lines to put them in the format Krona expects
        # 
        # Format:
        # [0] Unique match accession (e.g., RMK91773.1) 
        # [1] Match line with additional pipe (e.g., ./GCA_003698635.1_ASM369863v1_genomic.gbff.gz||MCMZ01000023|RMK91773.1|?|57767|57970|hypothetical)
        # [2-5] Doesn't matter as long as they're tab-separated
        # [6-9] Add additional tab-separated items
        # [10] evalue

        lines = []

        if args.raw:
            # Using raw PSI-BLAST output:
            # -outfmt '6 qacc sacc pident qlen slen evalue'
            for line in f:
                line = line.strip().split()

                if len(line) != 6:
                    print(f"Warning: skipping line of unexpected length ({len(line)}) in PSI-BLAST output file: \n\t{' '.join(line)}")
                    continue

                line[0] = line[1].split("|")[2]

                line[1] = ".gz||".join(line[1].split(".gz|"))

                while len(line) < 11:
                    line.append(line[-1])

                lines.append(line)
        else:
            # Using parsed PSI-BLAST output:
            # GBFF_NAME MATCH_ACCESSION E_VALUE QUERY_ACCESSION PID QUERY_LEN MATCH_LEN MATCH_LEN/QUERY_LEN
            for line in f:
                line = line.strip().split()

                if len(line) != 8:
                    print(f"Warning: skipping line of unexpected length ({len(line)}) in parsed PSI-BLAST output file: \n\t{' '.join(line)}")
                    continue

                line[0] = line[1]
                line[1] = f'gbff|blank|locus|{line[1]}|?|start|stop|annotation'
                
                while len(line) < 11:
                    line.append(line[2])
                
                lines.append(line)

else:
    print(f"Error: provided file '{args.psiblast_outfile}' not found. Please verify the path is correct.")
    exit()

# if args.gb_files:
#     # args.gb_files is just a one-item list containing a space-delimited string of the filenames
#     filenames = args.gb_files[0].split()

#     # Pull accessions from filenames
#     accessions = [name.strip().split("_")[-2] for name in filenames]

#     # Filter PSI-BLAST output lines by the provided accessions
#     filtered = []

