#         else:
#             accession_map[line_accession] = [line]

#     for accession in accessions:
#         if accession in accession_map:
#             filtered += [lines[line] for line in accession_map[accession]]
#         else:
#             print(f"Warning: accession '{accession}' not found in PSI-BLAST output file.")


if args.gb_dir:
    # Map the PSI-BLAST accessions in a dict for quicker lookups (may need to switch to a sortedlist for memory)
    accession_map = {}
    for i in range(len(lines)):
        line = lines[i]
        line_acc = line[1].split("|")[3]
        if line_acc in accession_map:
            continue # Ignore duplicate accessions
        else:
            accession_map[line_acc] = line

    # List to store the PSI-BLAST output lines by the provided accessions
    filtered = []

    filename_generator = glob.iglob(path.join(args.gb_dir, '*.gb')) # Using a generator in case A TON of GBs

    for filename in filename_generator:
        accession = filename.strip().split("_")[-2]

        # Check if the chars before the accession are part of the accession (e.g., WP_). Only possibilities should be the protein RefSeq accessions (.P_). There are several exceptions, just checking for upper case alpha
        potential_prefix = filename.strip().split("_")[-3]
        if len(potential_prefix) == 2 and potential_prefix.isalpha() and potential_prefix.isupper():
            # Valid RefSeq prefix
            accession = potential_prefix + "_" + accession

        match = accession_map.get(accession)

        if match:
            filtered.append(match)
        else:
            print(f"Warning: accession '{accession}' not found in PSI-BLAST output file.")

else:
    # If no accessions specified, filtered is everything
    filtered = lines

# Save filtered in a temp file
temp_name = "tmp_krona"
while path.exists(f"{temp_name}.txt"):
    temp_name += str(randint(0, 99))

temp_name += ".txt"

with open(temp_name, "w") as f:
    f.write("\n".join(["\t".join(line) for line in filtered]))


# Parse output location before running Krona
def iterate_filename(filename):
    """
    Adds an iterative integer to the end of a filename (before the extension) to prevent overwrites.
    :param filename: Str filename (and path) to check if it exists & iterate name if it does
    Return: new filename/location
    """
    if not path.exists(filename):
        return filename

    extension = filename.split('.')[-1]
    filename = '.'.join(filename.split('.')[0:-1])
    i = 0
    while path.exists(f"{filename}_{str(i)}.{extension}"):
        i += 1
    filename = f"{filename}_{str(i)}.{extension}"

    print(f"Warning: Provided output file already exists. Writing to '{filename}' instead.")

    return filename

if path.isdir(args.output):
    # Provided a directory to write to, just use default name
    output = path.join(args.output, "blast.krona")
else:
    output = args.output
output = iterate_filename(output)


# Get path to ImportBLAST.pl
script_path = os.path.abspath(__file__)
script_dir = os.path.dirname(script_path)

krona_path = os.path.join(script_dir, "Krona", "KronaTools", "scripts")
importblastpl_path = os.path.join(krona_path, "ImportBLAST.pl")

# Run Krona on the temp file
subprocess.run([importblastpl_path, 
               temp_name,
               "-o", output], 
               stdout=subprocess.DEVNULL,
               stderr=subprocess.DEVNULL) # Doing this to suppress warning messages, unfortunately also blocks errors

# Remove the temp file
os.remove(temp_name)
